window.CIVIL_SET_DATA["past-18"] = {"title":"Past Paper Set 18","negativeMarking":0,"chapters":[{"name":"Basic Civil Engineering","questions":[{"id":"PAST-18-002","src":"PAST-18-002","text":"If the free haul distance is 200 m, the cost of borrow (including excavation and hauling) is Rs. 4/m<sup>3</sup> at the station and the cost of haulage beyond free haul is Rs. 0.75/m<sup>3</sup> per station (30 m), what is the limit of economical haul distance?","options":[{"key":"a","text":"340 m"},{"key":"b","text":"360 m"},{"key":"c","text":"380 m"},{"key":"d","text":"400 m"}],"answer":"b","explanation":"The overhaul worth paying for is \\[\\dfrac{4}{0.75} = 5.33\\ \\text{stations}\\] or \\(5.33 \\times 30 = 160\\) m. The limit of economical haul is \\[200 + 160 = 360\\ \\text{m}\\]","marks":1,"source":{"kind":"past","set":18,"question":2,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q2 · 1 mark"},"topic":"ACiE0106"},{"id":"PAST-18-007","src":"PAST-18-007","text":"Which of the following methods of contouring is most suitable for a hilly terrain?","options":[{"key":"a","text":"Direct method"},{"key":"b","text":"Square method"},{"key":"c","text":"Cross-sections method"},{"key":"d","text":"Tachometric method"}],"answer":"d","explanation":"Tacheometry measures distances and heights quickly over rough, steep ground without chaining, which suits contouring in hilly terrain.","marks":1,"source":{"kind":"past","set":18,"question":7,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q7 · 1 mark"},"topic":"ACiE0105"},{"id":"PAST-18-021","src":"PAST-18-021","text":"Quartzite is a","options":[{"key":"a","text":"organic rock"},{"key":"b","text":"siliceous rock"},{"key":"c","text":"inorganic rock"},{"key":"d","text":"calcareous rock"}],"answer":"b","explanation":"Quartzite (metamorphosed sandstone) consists mainly of silica, so it is a siliceous rock.","marks":1,"source":{"kind":"past","set":18,"question":21,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q21 · 1 mark"},"topic":"ACiE0101"},{"id":"PAST-18-026","src":"PAST-18-026","text":"The water absorption for a first class brick should not be more than","options":[{"key":"a","text":"15%"},{"key":"b","text":"20%"},{"key":"c","text":"22%"},{"key":"d","text":"25%"}],"answer":"a","explanation":"The key follows the classification allowing first-class bricks at most about 15% water absorption after 24 hours' immersion (second class about 20%).","marks":1,"source":{"kind":"past","set":18,"question":26,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q26 · 1 mark"},"topic":"ACiE0102"},{"id":"PAST-18-036","src":"PAST-18-036","text":"The height of instrument method of levelling is","options":[{"key":"a","text":"more accurate than the rise and fall method"},{"key":"b","text":"less accurate than the rise and fall method"},{"key":"c","text":"quicker and less tedious for a large number of intermediate sights"},{"key":"d","text":"none of the above"}],"answer":"c","explanation":"The HI method reduces each reading simply as HI − staff reading, so it is quick when there are many intermediate sights. Rise and fall gives a complete arithmetic check and is more precise.","marks":1,"source":{"kind":"past","set":18,"question":36,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q36 · 1 mark"},"topic":"ACiE0105"},{"id":"PAST-18-039","src":"PAST-18-039","text":"Find the volume of stone required on a guide bund of slope 2:1 having length = 100 m, height = 5 m and thickness = 1 m.","options":[{"key":"a","text":"11.84 m<sup>3</sup>"},{"key":"b","text":"250 m<sup>3</sup>"},{"key":"c","text":"500 m<sup>3</sup>"},{"key":"d","text":"1184 m<sup>3</sup>"}],"answer":"d","explanation":"The sloping length is \\[5\\sqrt{1 + 2^2} = 5\\sqrt{5} \\approx 11.18\\ \\text{m}\\] so the volume is \\[11.18 \\times 100 \\times 1 \\approx 1118\\ \\text{m}^3\\] Option (d), 1184 m<sup>3</sup>, is the intended answer; its digits are transposed in the paper.","marks":1,"source":{"kind":"past","set":18,"question":39,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q39 · 1 mark"},"topic":"ACiE0106"},{"id":"PAST-18-041","src":"PAST-18-041","text":"If an irrigation channel has a side slope of \\(s:1\\), width \\(b\\), depth \\(d\\) and length \\(L\\), then the area of the side slopes of the trapezoidal channel is","options":[{"key":"a","text":"\\(A = 2Ly\\sqrt{1+z^2}\\)"},{"key":"b","text":"\\(A = 2LB\\sqrt{1+z^2}\\)"},{"key":"c","text":"\\(A = Ly\\sqrt{1+z^2}\\)"},{"key":"d","text":"\\(A = L\\sqrt{y(1+z^2)}\\)"}],"answer":"a","explanation":"Each sloping side is \\(y\\sqrt{1 + z^2}\\) long, so the two sides over length \\(L\\) cover \\[A = 2Ly\\sqrt{1 + z^2}\\] (the lining area). (The paper drops the root signs.)","marks":1,"source":{"kind":"past","set":18,"question":41,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q41 · 1 mark"},"topic":"ACiE0106"},{"id":"PAST-18-048","src":"PAST-18-048","text":"What is the moment of inertia of a rectangular section about the horizontal axis through its centroid?","options":[{"key":"a","text":"\\(\\dfrac{bd^3}{12}\\)"},{"key":"b","text":"\\(\\dfrac{bd^3}{3}\\)"},{"key":"c","text":"\\(\\dfrac{bd^3}{36}\\)"},{"key":"d","text":"\\(\\dfrac{bd^2}{6}\\)"}],"answer":"a","explanation":"About the centroidal horizontal axis, \\[I_{xx} = \\dfrac{bd^3}{12}\\] \\(\\dfrac{bd^3}{3}\\) is about the base, and \\(\\dfrac{bd^2}{6}\\) is the section modulus.","marks":1,"source":{"kind":"past","set":18,"question":48,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q48 · 1 mark"},"topic":"ACiE0104"}]},{"name":"Soil Mechanics and Foundation Engineering","questions":[{"id":"PAST-18-016","src":"PAST-18-016","text":"A foundation is called a deep foundation when","options":[{"key":"a","text":"\\((B/D) \\lt 1\\)"},{"key":"b","text":"\\((D/B) \\lt 1\\)"},{"key":"c","text":"\\((B/D) \\lt 4\\)"},{"key":"d","text":"\\((B/D) \\gt 4\\)"}],"answer":"a","explanation":"Terzaghi calls a foundation deep when its depth exceeds its width (D/B &gt; 1, i.e. B/D &lt; 1). Shallow foundations have D ≤ B. The source key gives (d), which inverts the ratio: it intends D/B &gt; 4, not B/D &gt; 4.","marks":1,"source":{"kind":"past","set":18,"question":16,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q16 · 1 mark"},"topic":"ACiE0205"},{"id":"PAST-18-023","src":"PAST-18-023","text":"If a soil has a liquid limit of 60% and a plastic limit of 40%, then the soil falls under","options":[{"key":"a","text":"MH"},{"key":"b","text":"CH"},{"key":"c","text":"LH"},{"key":"d","text":"ML"}],"answer":"a","explanation":"Here \\(\\text{PI} = 20\\). The A-line gives \\[\\text{PI}_A = 0.73(60 - 20) = 29.2\\] so the soil plots below it, and with \\(\\text{LL} \\gt 50\\) it is MH (high-plasticity silt).","marks":1,"source":{"kind":"past","set":18,"question":23,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q23 · 1 mark"},"topic":"ACiE0201"},{"id":"PAST-18-025","src":"PAST-18-025","text":"The formula for the degree of saturation is","options":[{"key":"a","text":"\\(\\dfrac{V_w}{V_v}\\)"},{"key":"b","text":"\\(\\dfrac{V_v}{V_w}\\)"},{"key":"c","text":"\\(\\dfrac{V_w}{V_s}\\)"},{"key":"d","text":"\\(\\dfrac{V_s}{V_w}\\)"}],"answer":"a","explanation":"The degree of saturation is the fraction of the voids filled with water: \\[S = \\dfrac{V_w}{V_v}\\] (0 for dry and 1 for saturated soil).","marks":1,"source":{"kind":"past","set":18,"question":25,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q25 · 1 mark"},"topic":"ACiE0201"},{"id":"PAST-18-037","src":"PAST-18-037","text":"A vertical cut is to be made in a soil mass having cohesion \\(c\\), angle of internal friction \\(\\phi\\) and unit weight \\(\\gamma\\). Considering \\(K_a\\) and \\(K_p\\) as the coefficients of active and passive earth pressures respectively, the maximum depth of unsupported excavation is","options":[{"key":"a","text":"\\(\\dfrac{4c}{\\gamma\\sqrt{K_a}}\\)"},{"key":"b","text":"\\(\\dfrac{4c\\sqrt{K_a}}{\\gamma}\\)"},{"key":"c","text":"\\(\\dfrac{4c}{\\gamma\\sqrt{K_p}}\\)"},{"key":"d","text":"\\(\\dfrac{4c\\sqrt{K_p}}{\\gamma}\\)"}],"answer":"a","explanation":"The net active thrust on an unsupported vertical cut is zero at a depth of twice the tension-crack depth: \\[H_c = \\dfrac{4c}{\\gamma\\sqrt{K_a}}\\]","marks":1,"source":{"kind":"past","set":18,"question":37,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q37 · 1 mark"},"topic":"ACiE0204"},{"id":"PAST-18-046","src":"PAST-18-046","text":"When the water table rises to the ground level, the ultimate bearing capacity of a shallow foundation on sand is reduced to","options":[{"key":"a","text":"40%"},{"key":"b","text":"50%"},{"key":"c","text":"60%"},{"key":"d","text":"75%"}],"answer":"b","explanation":"Submergence roughly halves the effective unit weight (\\(\\gamma' \\approx \\dfrac{\\gamma}{2}\\)), and both the surcharge and width terms of a cohesionless soil depend on it. The bearing capacity therefore falls to about 50%.","marks":1,"source":{"kind":"past","set":18,"question":46,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q46 · 1 mark"},"topic":"ACiE0206"},{"id":"PAST-18-055","src":"PAST-18-055","text":"Which of the following is not an assumption of Terzaghi's (consolidation theory)?","options":[{"key":"a","text":"Stokes law is valid"},{"key":"b","text":"soil is fully saturated"},{"key":"c","text":"soil is homogeneous and isotropic"},{"key":"d","text":"Darcy law is valid for the hydraulic gradient"}],"answer":"a","explanation":"Terzaghi's one-dimensional consolidation theory assumes saturated, homogeneous, isotropic soil, incompressible water and solids, and Darcy's law. Stokes' law, for settling particles, plays no part.","marks":1,"source":{"kind":"past","set":18,"question":55,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q55 · 1 mark"},"topic":"ACiE0206"},{"id":"PAST-18-080","src":"PAST-18-080","text":"A pycnometer containing 400 gm sand and water full to the top is 2150 gm. If the clear water plus pycnometer weight is 1950 gm and the specific gravity of the soil sample is 2.5, the water content of the sample is","options":[{"key":"a","text":"15%"},{"key":"b","text":"20%"},{"key":"c","text":"25%"},{"key":"d","text":"10%"}],"answer":"b","explanation":"The pycnometer relation gives, as a fraction, \\[w = \\dfrac{W_2 - W_1}{W_3 - W_4} \\times \\dfrac{G - 1}{G} - 1\\] so \\[\\begin{aligned} w &amp;= \\dfrac{400}{200} \\times 0.6 - 1 \\\\ &amp;= 0.20 = 20\\% \\end{aligned}\\]","marks":2,"source":{"kind":"past","set":18,"question":80,"marks":2,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q80 · 2 marks"},"topic":"ACiE0201"}]},{"name":"Basic Water Resources Engineering","questions":[{"id":"PAST-18-022","src":"PAST-18-022","text":"A liquid will not wet the surface of a solid if the angle of contact is","options":[{"key":"a","text":"acute"},{"key":"b","text":"unity"},{"key":"c","text":"obtuse"},{"key":"d","text":"zero"}],"answer":"c","explanation":"A contact angle above 90° (obtuse), as with mercury on glass, means adhesion is weaker than cohesion, so the liquid does not wet the surface.","marks":1,"source":{"kind":"past","set":18,"question":22,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q22 · 1 mark"},"topic":"ACiE0301"},{"id":"PAST-18-038","src":"PAST-18-038","text":"If the area is 72 hectares, the intensity of rainfall is 10 cm/hr and the runoff coefficient is 0.5, then find the discharge of the storm water.","options":[{"key":"a","text":"1.0 m<sup>3</sup>/s"},{"key":"b","text":"10 m<sup>3</sup>/s"},{"key":"c","text":"11 m<sup>3</sup>/s"},{"key":"d","text":"100 m<sup>3</sup>/s"}],"answer":"b","explanation":"With \\(I = 100\\) mm per h and \\(A = 72\\) ha, \\[\\begin{aligned} Q &amp;= \\dfrac{CIA}{360} = \\dfrac{0.5 \\times 100 \\times 72}{360} \\\\ &amp;= 10\\ \\text{m}^3\\text{/s} \\end{aligned}\\]","marks":1,"source":{"kind":"past","set":18,"question":38,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q38 · 1 mark"},"topic":"ACiE0306"},{"id":"PAST-18-040","src":"PAST-18-040","text":"Which of the following equations represents a possible 2-D incompressible flow?","options":[{"key":"a","text":"\\(\\dfrac{\\partial u}{\\partial x} + \\dfrac{\\partial v}{\\partial y} = 0\\)"},{"key":"b","text":"\\(\\dfrac{\\partial u}{\\partial y} + \\dfrac{\\partial v}{\\partial x} = 0\\)"},{"key":"c","text":"\\(\\dfrac{\\partial u}{\\partial v} + \\dfrac{\\partial x}{\\partial y} = 0\\)"},{"key":"d","text":"\\(\\dfrac{\\partial v}{\\partial u} + \\dfrac{\\partial y}{\\partial x} = 0\\)"}],"answer":"a","explanation":"For steady, incompressible, plane flow the continuity equation is \\[\\dfrac{\\partial u}{\\partial x} + \\dfrac{\\partial v}{\\partial y} = 0\\]","marks":1,"source":{"kind":"past","set":18,"question":40,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q40 · 1 mark"},"topic":"ACiE0303"},{"id":"PAST-18-044","src":"PAST-18-044","text":"When the barometer reads 740.0 mm of mercury, a pressure of 10 kPa suction at that location is equivalent to","options":[{"key":"a","text":"10.02 m of water (abs)"},{"key":"b","text":"9.87 m of water"},{"key":"c","text":"88.72 kPa (abs)"},{"key":"d","text":"0.043 kPa (abs)"}],"answer":"c","explanation":"The atmospheric pressure is \\[\\begin{aligned} p_{atm} &amp;= 0.740 \\times 13{,}600 \\times 9.81 \\\\ &amp;\\approx 98.7\\ \\text{kPa} \\end{aligned}\\] so \\[p_{abs} = 98.7 - 10 \\approx 88.7\\ \\text{kPa}\\]","marks":1,"source":{"kind":"past","set":18,"question":44,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q44 · 1 mark"},"topic":"ACiE0302"},{"id":"PAST-18-050","src":"PAST-18-050","text":"Flow in a channel is called laminar flow if the Reynolds number is","options":[{"key":"a","text":"Re &lt; 500"},{"key":"b","text":"Re &gt; 2000"},{"key":"c","text":"Re 500–2000"},{"key":"d","text":"All of the above"}],"answer":"a","explanation":"For open channels (Re based on hydraulic radius), flow is laminar below about 500, transitional between 500 and 2000 and turbulent above that.","marks":1,"source":{"kind":"past","set":18,"question":50,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q50 · 1 mark"},"topic":"ACiE0305"},{"id":"PAST-18-056","src":"PAST-18-056","text":"Bernoulli's principle is based on the law of conservation of","options":[{"key":"a","text":"power"},{"key":"b","text":"volume"},{"key":"c","text":"mass"},{"key":"d","text":"energy"}],"answer":"d","explanation":"Bernoulli's equation expresses conservation of mechanical energy along a streamline for ideal flow. Continuity expresses conservation of mass.","marks":1,"source":{"kind":"past","set":18,"question":56,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q56 · 1 mark"},"topic":"ACiE0303"},{"id":"PAST-18-064","src":"PAST-18-064","text":"If a weight of 120 kN on earth is equal to how much on the moon?","options":[{"key":"a","text":"20 kN"},{"key":"b","text":"30 kN"},{"key":"c","text":"40 kN"},{"key":"d","text":"45 kN"}],"answer":"a","explanation":"The moon's gravity is about one-sixth of Earth's, so the weight is \\[\\dfrac{120}{6} = 20\\ \\text{kN}\\]","marks":2,"source":{"kind":"past","set":18,"question":64,"marks":2,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q64 · 2 marks"},"topic":"ACiE0302"},{"id":"PAST-18-072","src":"PAST-18-072","text":"The area of a channel section is 8 m<sup>2</sup> and the wetted perimeter is 8 m. Calculate the value of the bed slope of the channel if the discharge is 33.33 m<sup>3</sup>/s and Manning's coefficient is 0.012.","options":[{"key":"a","text":"1 in 300"},{"key":"b","text":"1 in 400"},{"key":"c","text":"1 in 500"},{"key":"d","text":"1 in 600"}],"answer":"b","explanation":"Here \\(R = 1\\) m and \\(V = 4.17\\) m per s, so \\[\\begin{aligned} S &amp;= \\left(\\dfrac{nV}{R^{2{/}3}}\\right)^2 \\\\ &amp;= (0.012 \\times 4.17)^2 \\approx \\dfrac{1}{400} \\end{aligned}\\]","marks":2,"source":{"kind":"past","set":18,"question":72,"marks":2,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q72 · 2 marks"},"topic":"ACiE0305"},{"id":"PAST-18-073","src":"PAST-18-073","text":"Calculate the Froude number for a channel having a discharge of 261.03 m<sup>3</sup>/s, a cross-sectional area of 42 m<sup>2</sup> and a top width of 6 m.","options":[{"key":"a","text":"0.65"},{"key":"b","text":"0.72"},{"key":"c","text":"0.38"},{"key":"d","text":"0.75"}],"answer":"d","explanation":"The velocity is \\(V = \\dfrac{261.03}{42} = 6.22\\) m per s and the hydraulic depth is \\(D = \\dfrac{A}{T} = 7\\) m, so \\[\\text{Fr} = \\dfrac{6.22}{\\sqrt{9.81 \\times 7}} \\approx 0.75\\]","marks":2,"source":{"kind":"past","set":18,"question":73,"marks":2,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q73 · 2 marks"},"topic":"ACiE0305"}]},{"name":"Structural Mechanics","questions":[{"id":"PAST-18-011","src":"PAST-18-011","text":"If the SF is constant throughout the section, then the BM is","options":[{"key":"a","text":"constant"},{"key":"b","text":"linear"},{"key":"c","text":"parabolic"},{"key":"d","text":"cubic"}],"answer":"b","explanation":"Since \\(\\dfrac{dM}{dx} = V\\), a constant shear force gives a linearly varying bending moment (for example a cantilever with an end load).","marks":1,"source":{"kind":"past","set":18,"question":11,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q11 · 1 mark"},"topic":"ACiE0401"},{"id":"PAST-18-015","src":"PAST-18-015","text":"If a section is fixed at both ends, the crippling load is …… times that of the section having both ends hinged.","options":[{"key":"a","text":"Equal"},{"key":"b","text":"2 times"},{"key":"c","text":"4 times"},{"key":"d","text":"6 times"}],"answer":"c","explanation":"Fixing both ends halves the effective length, so \\[P = \\dfrac{\\pi^2EI}{(L{/}2)^2} = \\dfrac{4\\pi^2EI}{L^2}\\] four times the pin-ended load.","marks":1,"source":{"kind":"past","set":18,"question":15,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q15 · 1 mark"},"topic":"ACiE0403"},{"id":"PAST-18-028","src":"PAST-18-028","text":"In a simply supported beam with a point load acting at the centre, the strain energy will be","options":[{"key":"a","text":"\\(\\dfrac{W^2L^5}{240EI}\\)"},{"key":"b","text":"\\(\\dfrac{W^2L^5}{480EI}\\)"},{"key":"c","text":"\\(\\dfrac{W^2L^3}{48EI}\\)"},{"key":"d","text":"\\(\\dfrac{W^2L^3}{96EI}\\)"}],"answer":"d","explanation":"With \\(\\delta = \\dfrac{WL^3}{48EI}\\), \\[U = \\dfrac{1}{2}W\\delta = \\dfrac{W^2L^3}{96EI}\\]","marks":1,"source":{"kind":"past","set":18,"question":28,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q28 · 1 mark"},"topic":"ACiE0402"},{"id":"PAST-18-043","src":"PAST-18-043","text":"If \\(\\sigma_x\\) and \\(\\tau_{xy}\\) are the normal and shear stress respectively, then the minor principal stress will be","options":[{"key":"a","text":"\\(\\dfrac{\\sigma_x}{2} + \\sqrt{\\dfrac{\\sigma_x^2}{4} + \\tau_{xy}^2}\\)"},{"key":"b","text":"\\(\\dfrac{\\sigma_x}{2} - \\sqrt{\\dfrac{\\sigma_x^2}{4} - \\tau_{xy}^2}\\)"},{"key":"c","text":"\\(\\dfrac{\\sigma_x}{2} + \\sqrt{\\dfrac{\\sigma_x^2}{4} - \\tau_{xy}^2}\\)"},{"key":"d","text":"\\(\\dfrac{\\sigma_x}{2} - \\sqrt{\\dfrac{\\sigma_x^2}{4} + \\tau_{xy}^2}\\)"}],"answer":"d","explanation":"The minor principal stress is \\[\\sigma_2 = \\dfrac{\\sigma_x}{2} - \\sqrt{\\dfrac{\\sigma_x^2}{4} + \\tau_{xy}^2}\\] The + sign gives the major principal stress.","marks":1,"source":{"kind":"past","set":18,"question":43,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q43 · 1 mark"},"topic":"ACiE0402"},{"id":"PAST-18-045","src":"PAST-18-045","text":"The stiffness at the free (near) end if the far end is fixed is","options":[{"key":"a","text":"\\(0\\)"},{"key":"b","text":"\\(\\dfrac{EI}{L}\\)"},{"key":"c","text":"\\(\\dfrac{3EI}{L}\\)"},{"key":"d","text":"\\(\\dfrac{4EI}{L}\\)"}],"answer":"d","explanation":"With the far end fixed, a unit rotation at the near end requires a moment of 4EI/L.","marks":1,"source":{"kind":"past","set":18,"question":45,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q45 · 1 mark"},"topic":"ACiE0406"},{"id":"PAST-18-049","src":"PAST-18-049","text":"A plane truss has three members meeting at one top joint, each pinned at its lower end to a separate hinge support. The degree of static indeterminacy is","options":[{"key":"a","text":"0"},{"key":"b","text":"1"},{"key":"c","text":"2"},{"key":"d","text":"4"}],"answer":"b","explanation":"Here \\(m = 3\\), \\(r = 3 \\times 2 = 6\\) and \\(j = 4\\), so \\[\\begin{aligned} D_s &amp;= m + r - 2j \\\\ &amp;= 3 + 6 - 8 = 1 \\end{aligned}\\] (The paper shows the truss as a figure; the question is reworded.)","marks":1,"source":{"kind":"past","set":18,"question":49,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q49 · 1 mark"},"topic":"ACiE0405"},{"id":"PAST-18-051","src":"PAST-18-051","text":"In influence line diagrams (ILD)","options":[{"key":"a","text":"points remain fixed, position of load changes"},{"key":"b","text":"points change, position of loads remains fixed"},{"key":"c","text":"both of them change"},{"key":"d","text":"neither of them changes"}],"answer":"a","explanation":"An influence line shows the variation of a response at a fixed point as a unit load moves across the structure.","marks":1,"source":{"kind":"past","set":18,"question":51,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q51 · 1 mark"},"topic":"ACiE0404"},{"id":"PAST-18-074","src":"PAST-18-074","text":"A beam has a fixed end at A and a roller at the other end B. If a load of 10 kN is applied at an internal hinge at a distance l/3 from the fixed end, find the reaction at end B.","options":[{"key":"a","text":"0 kN"},{"key":"b","text":"2.5 kN"},{"key":"c","text":"7.5 kN"},{"key":"d","text":"10 kN"}],"answer":"a","explanation":"The segment from the hinge to B carries no load and cannot take moment at the hinge, so \\(R_B = 0\\). The fixed end carries the whole 10 kN.","marks":2,"source":{"kind":"past","set":18,"question":74,"marks":2,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q74 · 2 marks"},"topic":"ACiE0404"}]},{"name":"Design of Structures","questions":[{"id":"PAST-18-012","src":"PAST-18-012","text":"If the fineness modulus of a soil (sand) sample is high (more), then the sample will be","options":[{"key":"a","text":"fine sand"},{"key":"b","text":"coarse sand"},{"key":"c","text":"medium sand"},{"key":"d","text":"none"}],"answer":"b","explanation":"A higher fineness modulus means more material retained on the coarser sieves, i.e. coarser sand (FM 2.9–3.2 for coarse and 2.2–2.6 for fine).","marks":1,"source":{"kind":"past","set":18,"question":12,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q12 · 1 mark"},"topic":"ACiE0502"},{"id":"PAST-18-035","src":"PAST-18-035","text":"Imposed load is in which part of the IS code?","options":[{"key":"a","text":"IS 875 Part-I"},{"key":"b","text":"IS 875 Part-II"},{"key":"c","text":"IS 875 Part-III"},{"key":"d","text":"IS 875 Part-IV"}],"answer":"b","explanation":"IS 875 Part 2 covers imposed loads. Part 1 covers dead loads, Part 3 wind and Part 4 snow.","marks":1,"source":{"kind":"past","set":18,"question":35,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q35 · 1 mark"},"topic":"ACiE0501"},{"id":"PAST-18-042","src":"PAST-18-042","text":"Spot welding is used when two plates are placed","options":[{"key":"a","text":"one below the other"},{"key":"b","text":"one butting against the other"},{"key":"c","text":"one next to the other"},{"key":"d","text":"at right angles to each other"}],"answer":"a","explanation":"Spot welding fuses lapped (overlapping) sheets at points between electrodes, i.e. with one plate over the other.","marks":1,"source":{"kind":"past","set":18,"question":42,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q42 · 1 mark"},"topic":"ACiE0505"},{"id":"PAST-18-060","src":"PAST-18-060","text":"The moisture condition of aggregate used in concrete is","options":[{"key":"a","text":"saturated"},{"key":"b","text":"surface dry"},{"key":"c","text":"unsaturated and surface dry"},{"key":"d","text":"both (a) and (b)"}],"answer":"d","explanation":"Mix design assumes saturated surface-dry (SSD) aggregate, whose pores are filled but whose surface is dry. This is saturated and surface dry together.","marks":1,"source":{"kind":"past","set":18,"question":60,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q60 · 1 mark"},"topic":"ACiE0502"},{"id":"PAST-18-061","src":"PAST-18-061","text":"In a slab, the minimum thickness is designed to resist","options":[{"key":"a","text":"shear force"},{"key":"b","text":"axial force"},{"key":"c","text":"bending moment"},{"key":"d","text":"none of the above"}],"answer":"c","explanation":"Slab depth is fixed by the bending moment (together with span/depth limits for deflection). Shear is rarely critical in slabs. The source key gives (a), though its own note elsewhere says slab thickness is designed for bending.","marks":2,"source":{"kind":"past","set":18,"question":61,"marks":2,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q61 · 2 marks"},"topic":"ACiE0503"},{"id":"PAST-18-066","src":"PAST-18-066","text":"Why is a circular column not preferred in construction?","options":[{"key":"a","text":"It is difficult to make a connection with joints"},{"key":"b","text":"It is very expensive"},{"key":"c","text":"Designers hesitate"},{"key":"d","text":"All of the above"}],"answer":"a","explanation":"Rectangular beams do not frame neatly into a round column, which complicates formwork and joint detailing.","marks":2,"source":{"kind":"past","set":18,"question":66,"marks":2,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q66 · 2 marks"},"topic":"ACiE0503"},{"id":"PAST-18-077","src":"PAST-18-077","text":"What is the net section area of a steel plate 40 cm wide and 10 mm thick with one bolt, if the diameter of the bolt hole is 18 mm?","options":[{"key":"a","text":"38.2 cm<sup>2</sup>"},{"key":"b","text":"24 cm<sup>2</sup>"},{"key":"c","text":"578 mm<sup>2</sup>"},{"key":"d","text":"465 mm<sup>2</sup>"}],"answer":"a","explanation":"The net area is \\[\\begin{aligned} A_{net} &amp;= (400 - 18) \\times 10 \\\\ &amp;= 3820\\ \\text{mm}^2 = 38.2\\ \\text{cm}^2 \\end{aligned}\\]","marks":2,"source":{"kind":"past","set":18,"question":77,"marks":2,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q77 · 2 marks"},"topic":"ACiE0505"}]},{"name":"Water Supply, Sanitation and Environment","questions":[{"id":"PAST-18-006","src":"PAST-18-006","text":"The surface overflow rate (SOR) of a plain sedimentation tank is","options":[{"key":"a","text":"10000 to 12000 lit/day/m<sup>2</sup>"},{"key":"b","text":"12000 to 18000 lit/day/m<sup>2</sup>"},{"key":"c","text":"20000 to 22000 lit/day/m<sup>2</sup>"},{"key":"d","text":"22000 to 24000 lit/day/m<sup>2</sup>"}],"answer":"b","explanation":"Plain sedimentation (without coagulation) is designed for about 12,000-18,000 litres per day per m<sup>2</sup>. Tanks after coagulation take higher rates.","marks":1,"source":{"kind":"past","set":18,"question":6,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q6 · 1 mark"},"topic":"ACiE0603"},{"id":"PAST-18-020","src":"PAST-18-020","text":"Find the fire demand for 1 lakh population using Kuichling's formula.","options":[{"key":"a","text":"318.2 L/min"},{"key":"b","text":"31820 L/min"},{"key":"c","text":"3182 L/min"},{"key":"d","text":"318200 L/min"}],"answer":"b","explanation":"Kuichling's formula, with \\(P\\) in thousands and \\(Q\\) in litres per minute, is \\(Q = 3182\\sqrt{P}\\), so \\[Q = 3182 \\times \\sqrt{100} = 31{,}820\\] litres per minute.","marks":1,"source":{"kind":"past","set":18,"question":20,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q20 · 1 mark"},"topic":"ACiE0601"},{"id":"PAST-18-033","src":"PAST-18-033","text":"Steel dust after manufacturing falls under which of the following categories?","options":[{"key":"a","text":"Inorganic sludge"},{"key":"b","text":"Inorganic aqueous"},{"key":"c","text":"Liquid waste"},{"key":"d","text":"Organic aqueous"}],"answer":"a","explanation":"Dust from steel manufacturing, grinding and fabrication is a solid inorganic industrial residue, which the key classes as inorganic sludge waste.","marks":1,"source":{"kind":"past","set":18,"question":33,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q33 · 1 mark"},"topic":"ACiE0605"},{"id":"PAST-18-034","src":"PAST-18-034","text":"Activated sludge contains …… percent water.","options":[{"key":"a","text":"seventy-one"},{"key":"b","text":"ninety-seven"},{"key":"c","text":"sixty-six"},{"key":"d","text":"thirty-three"}],"answer":"b","explanation":"Waste activated sludge is very dilute, about 97–99% water (0.8–2.5% solids), which is why it must be thickened before digestion.","marks":1,"source":{"kind":"past","set":18,"question":34,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q34 · 1 mark"},"topic":"ACiE0605"},{"id":"PAST-18-047","src":"PAST-18-047","text":"The solid content of sewage is usually","options":[{"key":"a","text":"10%"},{"key":"b","text":"1%"},{"key":"c","text":"0.1%"},{"key":"d","text":"0.5%"}],"answer":"c","explanation":"Domestic sewage is about 99.9% water. Only about 0.1% is solids (organic and inorganic, dissolved and suspended).","marks":1,"source":{"kind":"past","set":18,"question":47,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q47 · 1 mark"},"topic":"ACiE0605"},{"id":"PAST-18-052","src":"PAST-18-052","text":"What percentage of activated sludge is recycled?","options":[{"key":"a","text":"20-30%"},{"key":"b","text":"30-40%"},{"key":"c","text":"40-50%"},{"key":"d","text":"50-60%"}],"answer":"a","explanation":"Part of the settled activated sludge is returned to the aeration tank to maintain the microbial population. The key gives a return of about 20–30% of the flow, while conventional plants often use 25–50%.","marks":1,"source":{"kind":"past","set":18,"question":52,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q52 · 1 mark"},"topic":"ACiE0605"},{"id":"PAST-18-053","src":"PAST-18-053","text":"Which of the following is not included in the three 'R's?","options":[{"key":"a","text":"Reuse"},{"key":"b","text":"Recycle"},{"key":"c","text":"Recover"},{"key":"d","text":"Reduce"}],"answer":"c","explanation":"The waste hierarchy's three Rs are Reduce, Reuse and Recycle. Recovery (of energy or materials) is a later step, not one of the three.","marks":1,"source":{"kind":"past","set":18,"question":53,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q53 · 1 mark"},"topic":"ACiE0605"},{"id":"PAST-18-065","src":"PAST-18-065","text":"Which of the following is used to remove algae?","options":[{"key":"a","text":"CO<sub>2</sub>"},{"key":"b","text":"Fungi"},{"key":"c","text":"Bacteria"},{"key":"d","text":"Copper sulphate"}],"answer":"d","explanation":"Copper sulphate (about 0.3–0.5 mg/L) is the standard algicide for reservoirs.","marks":2,"source":{"kind":"past","set":18,"question":65,"marks":2,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q65 · 2 marks"},"topic":"ACiE0603"},{"id":"PAST-18-067","src":"PAST-18-067","text":"Which of the following methods is used to determine the population of large and old cities?","options":[{"key":"a","text":"Arithmetic"},{"key":"b","text":"Geometric"},{"key":"c","text":"Arithmetical increase method"},{"key":"d","text":"Incremental increase method"}],"answer":"c","explanation":"Large, old cities grow by a roughly constant amount each decade, which suits the arithmetical increase method. Options (a) and (c) name the same method, and the key gives (c).","marks":2,"source":{"kind":"past","set":18,"question":67,"marks":2,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q67 · 2 marks"},"topic":"ACiE0601"}]},{"name":"Irrigation and Drainage","questions":[{"id":"PAST-18-057","src":"PAST-18-057","text":"The relative magnitude of tractive force and resistance to motion of a uniform sediment grain is expressed by","options":[{"key":"a","text":"\\(\\dfrac{\\tau_0}{(\\gamma_s + \\gamma_w)d} = C_c\\)"},{"key":"b","text":"\\(\\dfrac{\\tau_0}{(\\gamma_s - \\gamma_w)d} = C_c\\)"},{"key":"c","text":"\\(\\dfrac{\\tau_0}{\\gamma_s - \\gamma_w} \\times C_c\\)"},{"key":"d","text":"\\(\\dfrac{2\\tau_0 d}{\\gamma_s - \\gamma_w} = C_c\\)"}],"answer":"b","explanation":"The Shields parameter compares the bed shear stress with the submerged weight of the grain: τ<sub>0</sub>/[(γ<sub>s</sub> − γ<sub>w</sub>)d]. Motion begins when it reaches its critical value.","marks":1,"source":{"kind":"past","set":18,"question":57,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q57 · 1 mark"},"topic":"ACiE0702"},{"id":"PAST-18-059","src":"PAST-18-059","text":"When a canal is taken as an example, what factor causes its waterlogging?","options":[{"key":"a","text":"Seepage of water from high land"},{"key":"b","text":"Seepage through the canals"},{"key":"c","text":"Over and intensive irrigation"},{"key":"d","text":"Excessive rain"}],"answer":"b","explanation":"Seepage from unlined canals continually recharges the groundwater and raises the water table.","marks":1,"source":{"kind":"past","set":18,"question":59,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q59 · 1 mark"},"topic":"ACiE0706"},{"id":"PAST-18-078","src":"PAST-18-078","text":"A broad crested weir (\\(C_w = 1.5\\)) having length 30 m and height 2.5 m is placed across a river having an RL of upstream bed of 1080 m. If the discharge passing the weir is 90 m<sup>3</sup>/s, find the RL of the flood wall (take free board as 1.2 m).","options":[{"key":"a","text":"1085.82 m"},{"key":"b","text":"1084.08 m"},{"key":"c","text":"1081.58 m"},{"key":"d","text":"1085.28 m"}],"answer":"d","explanation":"The head over the weir is \\[\\begin{aligned} H &amp;= \\left(\\dfrac{90}{1.5 \\times 30}\\right)^{2{/}3} \\\\ &amp;= 2^{2{/}3} \\approx 1.59\\ \\text{m} \\end{aligned}\\] The flood level is \\[\\begin{aligned} &amp;1080 + 2.5 + 1.59 \\\\ &amp;= 1084.09\\ \\text{m} \\end{aligned}\\] and adding the 1.2 m freeboard gives about RL 1085.28 m.","marks":2,"source":{"kind":"past","set":18,"question":78,"marks":2,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q78 · 2 marks"},"topic":"ACiE0703"},{"id":"PAST-18-079","src":"PAST-18-079","text":"Calculate Lane's creep length (u/s cutoff = 5 m, floor length = 54 m, d/s cutoff = 8 m).","options":[{"key":"a","text":"48 m"},{"key":"b","text":"57 m"},{"key":"c","text":"44 m"},{"key":"d","text":"54 m"}],"answer":"c","explanation":"Lane's weighted creep is the vertical creep plus one-third of the horizontal: \\[\\begin{aligned} L &amp;= 2 \\times 5 + \\dfrac{54}{3} + 2 \\times 8 \\\\ &amp;= 10 + 18 + 16 = 44\\ \\text{m} \\end{aligned}\\]","marks":2,"source":{"kind":"past","set":18,"question":79,"marks":2,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q79 · 2 marks"},"topic":"ACiE0703"}]},{"name":"Hydropower","questions":[{"id":"PAST-18-001","src":"PAST-18-001","text":"Which of the following has the highest value of specific speed?","options":[{"key":"a","text":"Pelton wheel with single jet"},{"key":"b","text":"Francis"},{"key":"c","text":"Pelton with three jets"},{"key":"d","text":"Kaplan"}],"answer":"d","explanation":"Specific speed ranges roughly from 10–35 for a single-jet Pelton wheel (a little more with several jets) to 60–300 for Francis and 300–1000 for Kaplan turbines.","marks":1,"source":{"kind":"past","set":18,"question":1,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q1 · 1 mark"},"topic":"ACiE0806"},{"id":"PAST-18-005","src":"PAST-18-005","text":"The function of a surge tank is to","options":[{"key":"a","text":"supply water at constant pressure"},{"key":"b","text":"relieve water hammer pressures in the penstock pipe"},{"key":"c","text":"produce surge in the pipeline"},{"key":"d","text":"none of the above"}],"answer":"b","explanation":"The surge tank provides a free surface that absorbs flow changes, relieving water-hammer pressures in the penstock and conduit.","marks":1,"source":{"kind":"past","set":18,"question":5,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q5 · 1 mark"},"topic":"ACiE0805"},{"id":"PAST-18-027","src":"PAST-18-027","text":"The following operations are required for tunnelling in rocky terrain: 1. Removing the foul gases, 2. Marking the tunnel profile, 3. Setting up and drilling, 4. Checking misfire, 5. Mucking. The correct sequence is","options":[{"key":"a","text":"1, 2, 3, 4, 5"},{"key":"b","text":"2, 3, 5, 4, 1"},{"key":"c","text":"4, 2, 1, 3, 5"},{"key":"d","text":"2, 3, 1, 4, 5"}],"answer":"d","explanation":"The profile is marked, drilled and blasted. The fumes are cleared, misfires are checked, and then the muck is removed.","marks":1,"source":{"kind":"past","set":18,"question":27,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q27 · 1 mark"},"topic":"ACiE0805"},{"id":"PAST-18-031","src":"PAST-18-031","text":"In a hydel system, a forebay connects the","options":[{"key":"a","text":"penstock and turbine"},{"key":"b","text":"power channel and penstock"},{"key":"c","text":"power channel and tailrace channel"},{"key":"d","text":"headrace channel and penstock"}],"answer":"d","explanation":"The forebay is the basin at the end of the headrace (power) channel from which the penstocks draw water. Options (b) and (d) describe the same link, and the key gives (d).","marks":1,"source":{"kind":"past","set":18,"question":31,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q31 · 1 mark"},"topic":"ACiE0805"},{"id":"PAST-18-062","src":"PAST-18-062","text":"Micro hydro has various components like penstock, turbine etc. What is the function of the penstock?","options":[{"key":"a","text":"Penstocks are like large pipes laid with some slope"},{"key":"b","text":"Connect forebay and turbines"},{"key":"c","text":"An enclosed pipe that delivers water to hydro turbines"},{"key":"d","text":"None"}],"answer":"c","explanation":"The penstock's function is to deliver water under pressure, in an enclosed pipe, from the forebay to the turbine. Option (a) describes its form and (b) its location.","marks":2,"source":{"kind":"past","set":18,"question":62,"marks":2,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q62 · 2 marks"},"topic":"ACiE0805"}]},{"name":"Transportation","questions":[{"id":"PAST-18-003","src":"PAST-18-003","text":"The minimum ductility value for paving (bitumen) is","options":[{"key":"a","text":"50 cm"},{"key":"b","text":"60 cm"},{"key":"c","text":"75 cm"},{"key":"d","text":"100 cm"}],"answer":"c","explanation":"IS 73 requires at least 75 cm ductility at \\(27^\\circ\\text{C}\\) for the common paving grades (such as 80-100). Harder grades may be allowed 40-50 cm.","marks":1,"source":{"kind":"past","set":18,"question":3,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q3 · 1 mark"},"topic":"ACiE0903"},{"id":"PAST-18-008","src":"PAST-18-008","text":"The Benkelman beam deflection test point for a single lane (road) is","options":[{"key":"a","text":"0.6 m from edge"},{"key":"b","text":"0.9 m from edge"},{"key":"c","text":"0.6 m from center"},{"key":"d","text":"0.9 m from center"}],"answer":"a","explanation":"Deflection points are marked 0.6 m from the pavement edge on single-lane roads and 0.9 m from the edge on wider (two-lane) carriageways.","marks":1,"source":{"kind":"past","set":18,"question":8,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q8 · 1 mark"},"topic":"ACiE0905"},{"id":"PAST-18-009","src":"PAST-18-009","text":"The (penetration) grade for an 8.3 mm penetration falls under","options":[{"key":"a","text":"85/90"},{"key":"b","text":"85"},{"key":"c","text":"80/100"},{"key":"d","text":"85/100"}],"answer":"c","explanation":"8.3 mm is 83 units of 0.1 mm, which lies in the 80-100 penetration grade.","marks":1,"source":{"kind":"past","set":18,"question":9,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q9 · 1 mark"},"topic":"ACiE0903"},{"id":"PAST-18-010","src":"PAST-18-010","text":"What is the percentage content of asphalt in cut-back asphalt?","options":[{"key":"a","text":"10%"},{"key":"b","text":"30%"},{"key":"c","text":"50%"},{"key":"d","text":"80%"}],"answer":"d","explanation":"A cutback is bitumen thinned with a volatile solvent. The bitumen forms the major part (about 60–80%), and the key takes 80%.","marks":1,"source":{"kind":"past","set":18,"question":10,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q10 · 1 mark"},"topic":"ACiE0903"},{"id":"PAST-18-017","src":"PAST-18-017","text":"Dowel bars are placed along the …… of the road.","options":[{"key":"a","text":"longitudinal direction of traffic"},{"key":"b","text":"perpendicular to direction of traffic"},{"key":"c","text":"along 45° to the direction of traffic"},{"key":"d","text":"can be placed along any direction"}],"answer":"a","explanation":"Dowels cross the transverse joints parallel to the direction of traffic (the road's length), so they transfer wheel loads while letting the slabs slide lengthwise.","marks":1,"source":{"kind":"past","set":18,"question":17,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q17 · 1 mark"},"topic":"ACiE0905"},{"id":"PAST-18-018","src":"PAST-18-018","text":"The correction for Benkelman beam deflection is done as","options":[{"key":"a","text":"reduced 0.01 mm for every degree of temperature more than 35°C"},{"key":"b","text":"increased 0.01 mm for every degree of temperature less than 35°C"},{"key":"c","text":"no correction for deflection at 35°C and temperature less than 20°C"},{"key":"d","text":"all of above"}],"answer":"d","explanation":"Deflections are corrected to the standard 35°C at 0.01 mm per °C: subtract above 35°C and add below it. No correction is made at 35°C or for thin surfacings tested below about 20°C.","marks":1,"source":{"kind":"past","set":18,"question":18,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q18 · 1 mark"},"topic":"ACiE0905"},{"id":"PAST-18-019","src":"PAST-18-019","text":"The design speed for a 1st class road in plain terrain is","options":[{"key":"a","text":"120 kmph"},{"key":"b","text":"100 kmph"},{"key":"c","text":"80 kmph"},{"key":"d","text":"60 kmph"}],"answer":"a","explanation":"The Nepal Road Standard gives a design speed of 120 km/h for class I roads in plain terrain.","marks":1,"source":{"kind":"past","set":18,"question":19,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q19 · 1 mark"},"topic":"ACiE0902"},{"id":"PAST-18-024","src":"PAST-18-024","text":"The vertical clearance height of a cliff (overhang) in a hill road is","options":[{"key":"a","text":"4 m"},{"key":"b","text":"5 m"},{"key":"c","text":"6 m"},{"key":"d","text":"7 m"}],"answer":"b","explanation":"Hill roads cut under overhanging rock must leave a vertical clearance of about 5 m above the carriageway for vehicles.","marks":1,"source":{"kind":"past","set":18,"question":24,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q24 · 1 mark"},"topic":"ACiE0902"},{"id":"PAST-18-032","src":"PAST-18-032","text":"Rutting (failure) in a flexible pavement is","options":[{"key":"a","text":"12 mm or more"},{"key":"b","text":"1.2 mm"},{"key":"c","text":"10 mm"},{"key":"d","text":"20 mm or more"}],"answer":"d","explanation":"In mechanistic pavement design (IRC:37/DoR), a pavement is considered to have failed by rutting when the rut depth reaches 20 mm. Fatigue failure is 20% of the area cracked.","marks":1,"source":{"kind":"past","set":18,"question":32,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q32 · 1 mark"},"topic":"ACiE0905"},{"id":"PAST-18-054","src":"PAST-18-054","text":"The design speed of a rotary on an urban road is","options":[{"key":"a","text":"30 kmph"},{"key":"b","text":"35 kmph"},{"key":"c","text":"40 kmph"},{"key":"d","text":"45 kmph"}],"answer":"a","explanation":"IRC recommends a rotary design speed of 30 km/h in urban areas and 40 km/h in rural areas.","marks":1,"source":{"kind":"past","set":18,"question":54,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q54 · 1 mark"},"topic":"ACiE0904"},{"id":"PAST-18-058","src":"PAST-18-058","text":"The tie bars in a concrete pavement are provided across","options":[{"key":"a","text":"longitudinal joints"},{"key":"b","text":"vertical joints"},{"key":"c","text":"gap joints"},{"key":"d","text":"expansion joints"}],"answer":"a","explanation":"Tie bars across longitudinal joints hold adjacent lanes together and prevent them from separating. Dowels are used at transverse joints.","marks":1,"source":{"kind":"past","set":18,"question":58,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q58 · 1 mark"},"topic":"ACiE0905"},{"id":"PAST-18-068","src":"PAST-18-068","text":"The topmost part of the pavement is called","options":[{"key":"a","text":"surface course"},{"key":"b","text":"camber"},{"key":"c","text":"super elevation"},{"key":"d","text":"extra widening"}],"answer":"a","explanation":"The surface (wearing) course is the top layer in direct contact with traffic. Camber, superelevation and widening are geometric features.","marks":2,"source":{"kind":"past","set":18,"question":68,"marks":2,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q68 · 2 marks"},"topic":"ACiE0905"},{"id":"PAST-18-069","src":"PAST-18-069","text":"If the speed of the overtaken vehicle is 80 kmph, then the design speed is","options":[{"key":"a","text":"80 kmph"},{"key":"b","text":"96 kmph"},{"key":"c","text":"100 kmph"},{"key":"d","text":"106 kmph"}],"answer":"b","explanation":"The overtaken vehicle is assumed to travel 16 km per h slower than the design speed: \\[80 + 16 = 96\\ \\text{km/h}\\]","marks":2,"source":{"kind":"past","set":18,"question":69,"marks":2,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q69 · 2 marks"},"topic":"ACiE0902"},{"id":"PAST-18-071","src":"PAST-18-071","text":"A wheel base of 6.5 m negotiates a 35 m curve. Find the off tracking.","options":[{"key":"a","text":"0.5 m"},{"key":"b","text":"0.6 m"},{"key":"c","text":"0.62 m"},{"key":"d","text":"0.7 m"}],"answer":"b","explanation":"The off-tracking is \\[\\dfrac{l^2}{2R} = \\dfrac{6.5^2}{2 \\times 35} \\approx 0.60\\ \\text{m}\\]","marks":2,"source":{"kind":"past","set":18,"question":71,"marks":2,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q71 · 2 marks"},"topic":"ACiE0902"},{"id":"PAST-18-076","src":"PAST-18-076","text":"A Los Angeles abrasion test was conducted in the standard manner on an aggregate sample of 8 kg, and the weight of aggregate retained on the 1.7 mm sieve was found to be 6.2 kg. The Los Angeles abrasion value of the aggregate is","options":[{"key":"a","text":"35%"},{"key":"b","text":"45%"},{"key":"c","text":"18.26%"},{"key":"d","text":"22.5%"}],"answer":"d","explanation":"The abrasion loss is \\[\\dfrac{8 - 6.2}{8} \\times 100 = 22.5\\%\\]","marks":2,"source":{"kind":"past","set":18,"question":76,"marks":2,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q76 · 2 marks"},"topic":"ACiE0903"}]},{"name":"Project Planning, Design and Implementation","questions":[{"id":"PAST-18-004","src":"PAST-18-004","text":"The critical path is","options":[{"key":"a","text":"always the shortest path"},{"key":"b","text":"always the longest path"},{"key":"c","text":"maybe the shortest path"},{"key":"d","text":"maybe the longest path"}],"answer":"b","explanation":"The critical path is always the longest path through the network, and its length is the project duration. Its activities have zero float.","marks":1,"source":{"kind":"past","set":18,"question":4,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q4 · 1 mark"},"topic":"AALL1003"},{"id":"PAST-18-013","src":"PAST-18-013","text":"The fine imposed after the violation of copyright for the first time is","options":[{"key":"a","text":"NPR 10,000 to NPR 100,000, or six months in prison, or both"},{"key":"b","text":"up to two lakh rupees or imprisonment for a year, or both"},{"key":"c","text":"one lakh to two lakh rupees or imprisonment for a year, or both"},{"key":"d","text":"no fine for first time"}],"answer":"a","explanation":"Nepal's Copyright Act 2059 punishes a first offence with a fine of Rs 10,000–100,000, up to six months' imprisonment, or both. Repeat offences attract heavier penalties.","marks":1,"source":{"kind":"past","set":18,"question":13,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q13 · 1 mark"},"topic":"AALL1005"},{"id":"PAST-18-014","src":"PAST-18-014","text":"When was the Master's programme recognized by NEC?","options":[{"key":"a","text":"2076/09/06"},{"key":"b","text":"2066/06/23"},{"key":"c","text":"2077/05/26"},{"key":"d","text":"2079/05/05"}],"answer":"a","explanation":"Per the source, NEC began recognising master's programmes on 2076-09-06 BS. Bachelor's recognition dates from 2066-06-23, and the Act amendment from 2079-05-05.","marks":1,"source":{"kind":"past","set":18,"question":14,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q14 · 1 mark"},"topic":"AALL1006"},{"id":"PAST-18-029","src":"PAST-18-029","text":"The value (of a property) after the opening of the market is called","options":[{"key":"a","text":"Book value"},{"key":"b","text":"Market value"},{"key":"c","text":"Salvage value"},{"key":"d","text":"Scrap value"}],"answer":"b","explanation":"Market value is the price a property would fetch if sold in the open market at a given time.","marks":1,"source":{"kind":"past","set":18,"question":29,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q29 · 1 mark"},"topic":"AALL1002"},{"id":"PAST-18-030","src":"PAST-18-030","text":"The value when the owner sells the property for less than the market value is called","options":[{"key":"a","text":"Book value"},{"key":"b","text":"Market value"},{"key":"c","text":"Salvage value"},{"key":"d","text":"Distress value"}],"answer":"d","explanation":"Distress value is the reduced price obtained in a forced or urgent sale, below the normal market value.","marks":1,"source":{"kind":"past","set":18,"question":30,"marks":1,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q30 · 1 mark"},"topic":"AALL1002"},{"id":"PAST-18-063","src":"PAST-18-063","text":"If the initial investment for a machine is Rs 10000 and the depreciation amount per year is Rs 1600, then calculate the book value at the end of 5 years.","options":[{"key":"a","text":"Rs 1500"},{"key":"b","text":"Rs 2000"},{"key":"c","text":"Rs 2500"},{"key":"d","text":"Rs 8000"}],"answer":"b","explanation":"With straight-line depreciation, the book value is \\[\\begin{aligned} B &amp;= 10{,}000 - 5 \\times 1600 \\\\ &amp;= \\text{Rs } 2000 \\end{aligned}\\]","marks":2,"source":{"kind":"past","set":18,"question":63,"marks":2,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q63 · 2 marks"},"topic":"AALL1002"},{"id":"PAST-18-070","src":"PAST-18-070","text":"The expected time for a PERT event will be …… if the pessimistic time, optimistic time and most likely time are 10 days, 2 days and 3 days.","options":[{"key":"a","text":"3 days"},{"key":"b","text":"4 days"},{"key":"c","text":"5 days"},{"key":"d","text":"6 days"}],"answer":"b","explanation":"The expected time is \\[\\begin{aligned} t_e &amp;= \\dfrac{t_o + 4t_m + t_p}{6} \\\\ &amp;= \\dfrac{2 + 12 + 10}{6} = 4\\ \\text{days} \\end{aligned}\\]","marks":2,"source":{"kind":"past","set":18,"question":70,"marks":2,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q70 · 2 marks"},"topic":"AALL1003"},{"id":"PAST-18-075","src":"PAST-18-075","text":"How many members are selected by NEC itself?","options":[{"key":"a","text":"1"},{"key":"b","text":"2"},{"key":"c","text":"3"},{"key":"d","text":"4"}],"answer":"b","explanation":"The NEC Act provides for two engineers nominated by the Council itself.","marks":2,"source":{"kind":"past","set":18,"question":75,"marks":2,"date":"2080 Chaitra 29","shift":"2nd–3rd shift","reference":"Past Paper Set 18, Q75 · 2 marks"},"topic":"AALL1006"}]}]};
